import 'package:flutter/material.dart';
import '../../services/api_service.dart';
class SubscriptionsScreen extends StatefulWidget{const SubscriptionsScreen({super.key});@override State<SubscriptionsScreen> createState()=>_SubscriptionsScreenState();}
class _SubscriptionsScreenState extends State<SubscriptionsScreen>{List subscriptions=[],students=[];List<String> subjects=[];bool loading=true;static const fallback=['العربية','اللغة الإنجليزية','الرياضيات','العلوم','الدراسات الاجتماعية','Math','Science','English','Arabic','German','French','Spanish','Quran'];List<dynamic> list(dynamic x){if(x is List)return List<dynamic>.from(x);if(x is Map){final d=x['data'];if(d is List)return List<dynamic>.from(d);if(d is Map&&d['data'] is List)return List<dynamic>.from(d['data']);}return [];}int id(dynamic x)=>int.tryParse('${x['id']}')??0;String sub(dynamic x)=>x is Map?'${x['subject']??x['name']??''}':'$x';void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));@override void initState(){super.initState();load();}
Future<void> load()async{if(mounted)setState(()=>loading=true);Object? primaryError;try{final r=await ApiService.get('subscriptions');if(mounted)setState(()=>subscriptions=list(r));}catch(e){primaryError=e;}try{final r=await ApiService.get('students');if(mounted)setState(()=>students=list(r));}catch(e){if(primaryError==null)primaryError=e;}try{final r=await ApiService.get('subjects');final ss=list(r).map(sub).where((x)=>x.isNotEmpty).toSet().toList();if(mounted)setState(()=>subjects=ss.isEmpty?fallback:ss);}catch(_){if(mounted)setState(()=>subjects=fallback);}if(mounted){setState(()=>loading=false);if(primaryError!=null)msg(primaryError!);}}
Future<void> form({dynamic item})async{if(students.isEmpty){msg(Exception('أضف طالبًا أولًا.'));return;}int studentId=id(item?['student']??{'id':item?['student_id']});String subject='${item?['subject']??subjects.first}';if(!subjects.contains(subject))subject=subjects.first;String status='${item?['status']??'active'}';String serviceType='${item?['service_type']??'group'}';String billingType='${item?['billing_type']??'monthly'}';final amount=TextEditingController(text:'${item?['amount']??''}'),lessonPrice=TextEditingController(text:'${item?['lesson_price']??item?['amount']??''}'),lessonCount=TextEditingController(text:'${item?['lesson_count']??8}'),start=TextEditingController(text:'${item?['starts_on']??''}'),end=TextEditingController(text:'${item?['ends_on']??''}');final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:Text(item==null?'إضافة اشتراك':'تعديل الاشتراك'),content:Form(key:k,child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(value:studentId,items:students.map((s)=>DropdownMenuItem(value:id(s),child:Text('${s['name']}'))).toList(),onChanged:(v){if(v!=null)set(()=>studentId=v);}),DropdownButtonFormField<String>(value:subject,items:subjects.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v){if(v!=null)set(()=>subject=v);}),TextFormField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'المبلغ *'),validator:(v)=>double.tryParse(v??'')==null?'مبلغ غير صحيح':null),TextFormField(controller:start,decoration:const InputDecoration(labelText:'البداية YYYY-MM-DD')),TextFormField(controller:end,decoration:const InputDecoration(labelText:'النهاية YYYY-MM-DD')),DropdownButtonFormField<String>(value:serviceType,items:const[DropdownMenuItem(value:'private',child:Text('Private — خاص')),DropdownMenuItem(value:'group',child:Text('Group — مجموعة'))],onChanged:(v){if(v!=null)set(()=>serviceType=v);},decoration:const InputDecoration(labelText:'نوع الخدمة')),DropdownButtonFormField<String>(value:billingType,items:const[DropdownMenuItem(value:'per_lesson',child:Text('بالحصة')),DropdownMenuItem(value:'monthly',child:Text('شهري'))],onChanged:(v){if(v!=null)set(()=>billingType=v);},decoration:const InputDecoration(labelText:'نظام الاشتراك')),TextFormField(controller:lessonPrice,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'سعر الحصة (Private)')),TextFormField(controller:lessonCount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'عدد حصص Group (افتراضي 8)')),DropdownButtonFormField<String>(value:status,items:const[DropdownMenuItem(value:'active',child:Text('نشط')),DropdownMenuItem(value:'inactive',child:Text('غير نشط')),DropdownMenuItem(value:'expired',child:Text('منتهي'))],onChanged:(v){if(v!=null)set(()=>status=v);})])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate())Navigator.pop(d,true);},child:const Text('حفظ'))])));if(ok==true){try{final b={'student_id':studentId,'subject':subject,'service_type':serviceType,'billing_type':serviceType=='private'?'per_lesson':billingType,'amount':double.parse(amount.text),'lesson_price':double.tryParse(lessonPrice.text),'lesson_count':int.tryParse(lessonCount.text),'starts_on':start.text.trim(),'ends_on':end.text.trim(),'status':status};if(item==null)await ApiService.post('subscriptions/enhanced',b);else await ApiService.put('subscriptions/${id(item)}',b);await load();}catch(e){msg(e);}}for(final c in[amount,lessonPrice,lessonCount,start,end])c.dispose();}
Future<void> remove(dynamic s)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('حذف الاشتراك'),content:const Text('هل تريد الحذف؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('subscriptions/${id(s)}');await load();}catch(e){msg(e);}}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('الاشتراكات'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>form(),icon:const Icon(Icons.add),label:const Text('إضافة اشتراك')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.fromLTRB(16,12,16,90),itemCount:subscriptions.length,itemBuilder:(_,i){final s=subscriptions[i],student=s['student'];return Card(child:ListTile(title:Text('${student?['name']??'طالب'}'),subtitle:Text('${s['subject']??''} • ${s['service_type']??'group'} • ${s['amount']??0}\n${s['starts_on']??''} → ${s['ends_on']??''} • ${s['status']??''}'),isThreeLine:true,trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>form(item:s),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>remove(s),icon:const Icon(Icons.delete))])));})));
}
